__d(function(g,r,i,a,m,e,d){Object.defineProperty(e,"__esModule",{value:!0}),e.FAQ_ITEMS=void 0;e.FAQ_ITEMS=[{q:'\uc2e4\ubc84\uc2a4\ud14c\uc774\ub294 \ubb34\ub8cc\uc778\uac00\uc694?',a:'\ub124. \uc2dc\uc124 \ud0d0\uc0c9\xb7\ube44\uc6a9 \ube44\uad50\xb7\uc720\ud615 \uc9c4\ub2e8\xb7\uc0c1\ub2f4 \ubc0f \ud22c\uc5b4 \uc608\uc57d\uae4c\uc9c0 \ubaa8\ub450 \ubb34\ub8cc\uc785\ub2c8\ub2e4. \uc774\uc6a9\ub8cc\ub098 \uc0c1\ub2f4 \uc218\uc218\ub8cc\ub97c \uc774\uc6a9\uc790\uc5d0\uac8c \ubc1b\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.'},{q:'\ud68c\uc6d0\uac00\uc785(\ub85c\uadf8\uc778)\uc744 \uaf2d \ud574\uc57c \ud558\ub098\uc694?',a:'\uc544\ub2c8\uc694. \uc2dc\uc124 \ucc3e\uae30\xb7\ube44\uad50\uc640 \uc0c1\ub2f4\xb7\ud22c\uc5b4 \uc608\uc57d\uc740 \ub85c\uadf8\uc778 \uc5c6\uc774 \ud558\uc2e4 \uc218 \uc788\uc5b4\uc694. \ube44\ud68c\uc6d0\uc73c\ub85c \uc2e0\uccad\ud558\uba74 \uc608\uc57d\ubc88\ud638\uac00 \ubc1c\uae09\ub418\uace0, \uadf8 \ubc88\ud638\ub85c \uc9c4\ud589 \uc0c1\ud0dc\ub97c \uc870\ud68c\xb7\ucde8\uc18c\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\n\ub2e4\ub9cc \uc2dc\uc124 \ub300\ud45c\ubc88\ud638\uc640 \uc815\ud655\ud55c \uc704\uce58(\uae38\ucc3e\uae30), \ud56d\ubaa9\ubcc4 \uc815\ud655\ud55c \uae08\uc561\uc740 \ub85c\uadf8\uc778 \ud6c4\uc5d0 \ubcf4\uc5ec\ub4dc\ub9bd\ub2c8\ub2e4. \ube44\ub85c\uadf8\uc778 \uc0c1\ud0dc\uc5d0\uc11c\ub294 \ub300\ub7b5\uc801\uc778 \uc704\uce58\uc640 \uae08\uc561 \uad6c\uac04\uae4c\uc9c0 \ud655\uc778\ud558\uc2e4 \uc218 \uc788\uc5b4\uc694.\n\ub85c\uadf8\uc778(\uce74\uce74\uc624\xb7\uc774\uba54\uc77c)\ud558\uba74 \ucc1c\ud55c \uc2dc\uc124\uacfc \uc0c1\ub2f4 \uc774\ub825\ub3c4 \uc5ec\ub7ec \uae30\uae30\uc5d0\uc11c \uc774\uc5b4 \ubcfc \uc218 \uc788\uc2b5\ub2c8\ub2e4.'},{q:'\ube44\uc6a9\xb7\uacf5\uc2e4 \uc815\ubcf4\ub294 \uc815\ud655\ud55c\uac00\uc694?',a:'\uc2dc\uc124 \uc815\ubcf4\ub294 \uacf5\uacf5\ub370\uc774\ud130, \uc2dc\uc124 \uacf5\uc2dd \uc790\ub8cc, \uc5b8\ub860 \ubcf4\ub3c4 \ub4f1 \uacf5\uac1c \uc790\ub8cc\ub97c \uc218\uc9d1\xb7\uc815\ub9ac\ud55c \uac83\uc73c\ub85c \ucc38\uace0\uc6a9\uc785\ub2c8\ub2e4. \uc2dc\uc124 \uc0ac\uc815\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc73c\ubbc0\ub85c, \uacc4\uc57d \uc804\uc5d0\ub294 \ubc18\ub4dc\uc2dc \uc2dc\uc124\uc5d0 \uc9c1\uc811 \ud655\uc778\ud558\uc2dc\uae30\ub97c \uad8c\ud569\ub2c8\ub2e4.\n\uac01 \uc815\ubcf4\uc5d0\ub294 \ucd9c\ucc98\uc640 \ucd5c\uadfc \ud655\uc778\uc77c\uc744 \ud45c\uc2dc\ud558\uba70, \uac80\uc99d \uc804 \uc790\ub8cc\uc5d0\ub294 \u300c\uc804\ud654 \ud655\uc778 \ud544\uc694\u300d \ub77c\ubca8\uc744 \ud568\uaed8 \ubcf4\uc5ec \ub4dc\ub9bd\ub2c8\ub2e4.'},{q:'\uc0c1\ub2f4\xb7\ud22c\uc5b4 \uc608\uc57d\uc740 \uc5b4\ub5bb\uac8c \uc9c4\ud589\ub418\ub098\uc694?',a:'\uc608\uc57d\uc744 \uc2e0\uccad\ud558\uba74 \uc785\ub825\ud558\uc2e0 \uc5f0\ub77d\ucc98\xb7\ud76c\ub9dd \uc77c\uc2dc\xb7\ubb38\uc758 \ub0b4\uc6a9\uc774 \ud574\ub2f9 \uc2dc\uc124 \ubc0f \ubc30\uc815\ub41c \uc0c1\ub2f4\uc0ac\uc5d0\uac8c \uc0c1\ub2f4 \uc5f0\uacb0 \ubaa9\uc801\uc73c\ub85c \uc804\ub2ec\ub429\ub2c8\ub2e4. \uc608\uc57d\uc740 \uc2dc\uc124\xb7\uc0c1\ub2f4\uc0ac\uc758 \ud655\uc778 \ud6c4 \ud655\uc815\ub418\uba70, \uc2e0\uccad\ub9cc\uc73c\ub85c \ud655\uc815\ub418\uc9c0\ub294 \uc54a\uc2b5\ub2c8\ub2e4.\n\uc2e4\ubc84\uc2a4\ud14c\uc774\ub294 \uc2dc\uc124\uacfc \uc774\uc6a9\uc790 \uac04 \uacc4\uc57d\uc758 \ub2f9\uc0ac\uc790\uac00 \uc544\ub2c8\uba70, \uc785\uc8fc \uacc4\uc57d\uc758 \ub0b4\uc6a9\xb7\uc774\ud589\uc5d0 \ub300\ud574\uc11c\ub294 \ucc45\uc784\uc744 \uc9c0\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.'},{q:'\uc5b4\ub5a4 \uc2dc\uc124\uc744 \ub2e4\ub8e8\ub098\uc694?',a:'\uc2e4\ubc84\ud0c0\uc6b4(\ub178\uc778\ubcf5\uc9c0\uc8fc\ud0dd), \uc694\uc591\uc6d0\xb7\uc694\uc591\ubcd1\uc6d0, \uc8fc\uc57c\uac04\ubcf4\ud638, \ubc29\ubb38\uc694\uc591 \ub4f1 \uc804\uad6d\uc758 \uc2dc\ub2c8\uc5b4 \uc8fc\uac70\xb7\ub3cc\ubd04 \uc2dc\uc124\uc744 \ub2e4\ub8f9\ub2c8\ub2e4. \ud648 \ud654\uba74\uc758 \ubd84\ub958\ub97c \ub20c\ub7ec \uc720\ud615\ubcc4\ub85c, \uc9c0\ub3c4\uc5d0\uc11c \uc9c0\uc5ed\ubcc4\ub85c \ucc3e\uc544\ubcfc \uc218 \uc788\uc5b4\uc694.'},{q:'\u300c\ub9de\ucda4 \uc9c4\ub2e8\u300d\uc740 \ubb34\uc5c7\uc778\uac00\uc694?',a:'\ubd80\ubaa8\ub2d8\uc758 \uc0c1\ud0dc\uc640 \uc870\uac74\uc5d0 \uad00\ud55c \uc9e7\uc740 \uc9c8\ubb38\uc5d0 \ub2f5\ud558\uba74, 30\ucd08 \ub9cc\uc5d0 \uc5b4\ub5a4 \uc720\ud615(\uc2e4\ubc84\ud0c0\uc6b4\xb7\uc694\uc591\xb7\uc7ac\uac00\ub3cc\ubd04 \ub4f1)\uc774 \ub9de\uc744\uc9c0 \ucd94\ucc9c\ud574 \ub4dc\ub9ac\ub294 \uae30\ub2a5\uc785\ub2c8\ub2e4. \ucd94\ucc9c \uacb0\uacfc\uc5d0 \ub9de\ucdb0 \ud648\uacfc \ubaa9\ub85d\uc758 \ucd94\ucc9c \uc2dc\uc124\uc774 \uac1c\uc778\ud654\ub429\ub2c8\ub2e4.'},{q:'\ub0b4 \uac1c\uc778\uc815\ubcf4\ub294 \uc548\uc804\ud558\uac8c \uad00\ub9ac\ub418\ub098\uc694?',a:'\uc608\uc57d \uc2dc \ubc1b\uc740 \uc5f0\ub77d\ucc98\ub294 \uc0c1\ub2f4 \uc5f0\uacb0 \ubaa9\uc801\uc73c\ub85c\ub9cc \uc0ac\uc6a9\ud558\uba70, \uc0c1\ub2f4 \uc885\ub8cc \ud6c4 \uc77c\uc815 \uae30\uac04 \ub4a4 \ud30c\uae30\ud569\ub2c8\ub2e4. \uc811\uc18d \uae30\ub85d\uc740 \uc218\uc9d1\uc77c\ub85c\ubd80\ud130 12\uac1c\uc6d4 \ud6c4 \ud30c\uae30\ud558\uace0, \uad11\uace0 \uc2dd\ubcc4\uc790\xb7\ub2e8\ub9d0 \uc704\uce58\uc815\ubcf4\ub294 \uc218\uc9d1\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\n\ud68c\uc6d0\uc740 \u300c\ub0b4 \uc815\ubcf4 \u2192 \ud68c\uc6d0 \ud0c8\ud1f4\u300d\ub85c \uc5b8\uc81c\ub4e0 \uacc4\uc815\xb7\ucc1c\xb7\uc0c1\ub2f4 \uc774\ub825\uc744 \uc989\uc2dc \uc0ad\uc81c\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc790\uc138\ud55c \ub0b4\uc6a9\uc740 \uac1c\uc778\uc815\ubcf4 \ucc98\ub9ac\ubc29\uce68\uc744 \ud655\uc778\ud574 \uc8fc\uc138\uc694.'},{q:'\uc0ac\uc9c4\uc774\ub098 \ub9ac\ubdf0\ub294 \uc5b4\ub5bb\uac8c \uc62c\ub9ac\ub098\uc694?',a:'\uc2dc\uc124 \uc0c1\uc138 \ud654\uba74\uc5d0\uc11c \ub85c\uadf8\uc778 \ud6c4 \uc0ac\uc9c4\uc744 \uc62c\ub9ac\uac70\ub098 \ubcf4\ud638\uc790 \ub9ac\ubdf0\ub97c \uc791\uc131\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc9c1\uc811 \ucd2c\uc601\ud588\uac70\ub098 \uc0ac\uc6a9 \uad8c\ud55c\uc774 \uc788\ub294 \uc0ac\uc9c4\ub9cc \uc62c\ub824 \uc8fc\uc138\uc694(\uc5c5\ub85c\ub4dc \uc2dc \uc704\uce58\uc815\ubcf4\ub294 \uc790\ub3d9 \uc81c\uac70\ub429\ub2c8\ub2e4). \ubcf8\uc778\uc774 \uc62c\ub9b0 \uc0ac\uc9c4\xb7\ub9ac\ubdf0\ub294 \uc5b8\uc81c\ub4e0 \uc9c1\uc811 \uc0ad\uc81c\ud560 \uc218 \uc788\uace0, \ubd80\uc801\uc808\ud55c \ucf58\ud150\uce20\ub294 \uc2e0\uace0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.'},{q:'\uc2dc\uc124 \uc815\ubcf4\uac00 \uc0ac\uc2e4\uacfc \ub2ec\ub77c\uc694 / \uc6b0\ub9ac \uc2dc\uc124\uc744 \ub4f1\ub85d\xb7\uc218\uc815\ud558\uace0 \uc2f6\uc5b4\uc694.',a:'\uc2dc\uc124 \uc0c1\uc138 \ud654\uba74 \ud558\ub2e8\uc758 \u300c\uc774 \uc2dc\uc124 \ub2f4\ub2f9\uc790\uc138\uc694?\u300d\uc5d0\uc11c \ub2f4\ub2f9\uc790 \uc778\uc99d\uc744 \uc2e0\uccad\ud558\uc2dc\uba74, \uacf5\uc2dd \uc0ac\uc9c4\uacfc \uc815\ubcf4\ub97c \uc9c1\uc811 \ub4f1\ub85d\xb7\uad00\ub9ac\ud558\uc2e4 \uc218 \uc788\uc2b5\ub2c8\ub2e4(\ubb34\ub8cc). \uc778\uc99d\ub418\uba74 \uc62c\ub9ac\uc2dc\ub294 \uc0ac\uc9c4\uc774 \u300c\uc2dc\uc124 \uacf5\uc2dd\u300d\uc73c\ub85c \ubc14\ub85c \uac8c\uc2dc\ub429\ub2c8\ub2e4. \uadf8 \ubc16\uc758 \uc815\uc815 \uc694\uccad\uc740 \ubb38\uc758\ub85c \uc54c\ub824 \uc8fc\uc138\uc694.'}]},933,[]);